//! The user LED (PA24) at 1 Hz on embassy-time, and a line a second over the
//! virtual COM port (SERCOM2, PA12/PA13, 115,200 baud) with the time since
//! boot and the chip's serial number: the clocks, GPIO, the blocking UART,
//! the time driver and the unique ID on the GV00. With `GV_DFLL=1` at build
//! time, the CPU runs from the DFLL48M locked to the board's crystal.

#![no_std]
#![no_main]
#![allow(clippy::used_underscore_binding, reason = "in code generated by embassy_executor::main")]

use core::fmt::Write;

use embassy_executor::Spawner;
use embassy_time::{Duration, Instant, Timer};
use panic_halt as _;
use pic32c_hal::clocks;
use pic32c_hal::gpio::{Level, Output};
use pic32cm_gv_curiosity_nano::Log;

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    let p = if option_env!("GV_DFLL") == Some("1") {
        pic32c_hal::init(pic32c_hal::Config::new(clocks::Config::dfll48m_from_xosc32k()))
    } else {
        pic32cm_gv_curiosity_nano::init()
    };
    let mut led = Output::new(p.PA24, Level::Low);
    let mut log = Log::init(p.SERCOM2, p.PA12, p.PA13);
    let f = clocks::frequencies();
    let _ = writeln!(log, "\npic32cm-gv-curiosity-nano blink, CPU {} Hz, DFLL48M {:?}", f.map_or(0, |f| f.cpu()), f.and_then(|f| f.dfll48m));
    let _ = write!(log, "serial number ");
    for byte in pic32c_hal::uid::unique_id() {
        let _ = write!(log, "{byte:02x}");
    }
    let _ = writeln!(log);
    let mut n = 0u32;
    loop {
        led.toggle();
        Timer::after(Duration::from_millis(500)).await;
        led.toggle();
        Timer::after(Duration::from_millis(500)).await;
        n += 1;
        let _ = writeln!(log, "tick {n}: {} ms since boot", Instant::now().as_millis());
    }
}
